export type { AppPluginTextKey };

function uncheckedAppPluginText(locale: NextMuxDesktopLocale, key: AppPluginTextKey, values: Readonly<Record<string, string | number>> = {}): string {
    const template = (catalog[locale] || catalog.en)[key] ?? catalog.en[key];
    return template.replace(/\{(\w+)\}/g, (all, name) => name in values ? String(values[name]) : all);
}

/** A run's end or an error code in words; an unknown code is shown as it is. */
export function appPluginReason(locale: NextMuxDesktopLocale, reason: string): string {
    if (reason === 'request_limit') return appPluginRuntimeText(locale, 'requestLimit');
    if (reason.startsWith('event:')) return appPluginText(locale, 'reason.event', { event: reason.slice(6) });
    const key = `reason.${reason}` as AppPluginTextKey;
    if (key in zhCN) return appPluginText(locale, key);
    const failure = modelFailure(locale, reason);
    return failure.kind !== 'unknown' || /^(?:decision|vision|model)_/.test(reason) ? failure.text : reason;
}

