export function appPluginError(locale: NextMuxDesktopLocale, error: unknown): string {
    if (error && typeof error === 'object') {
        const record = error as { error?: unknown; code?: unknown; kind?: unknown; readableError?: unknown; status?: unknown };
        const candidate = typeof record.error === 'string' && !record.kind && !record.readableError && !record.status ? record.error
            : typeof record.code === 'string' && !record.kind && !record.readableError && !record.status ? record.code : '';
        if (candidate && (appPluginInputError(locale, candidate) || appPluginPackageError(locale, candidate) || (`error.${candidate}` in zhCN))) {
            return appPluginError(locale, candidate);
        }
    }
    if (error === 'package_format_unsupported') return appPluginOptionsText(locale, 'unsupportedFormat');
    const packageError = appPluginPackageError(locale, error);
    if (packageError) return packageError;
    if (error === 'decision_protocol_unsupported') return `${appPluginText(locale, 'protocolExcluded')}. ${appPluginText(locale, 'openSettings')}`;
    if (error === 'decision_choice_only') return decisionChoiceOnlyCopy[locale] || decisionChoiceOnlyCopy.en;
    // Paid plugins (付费插件): no purchase, no sign-in, or the license could not be checked.
    const paid: Readonly<Record<string, AppPluginTextKey>> = { plugin_purchase_required: 'needPurchase', plugin_login_required: 'loginToBuy',
        license_unavailable: 'licenseUnavailable', license_invalid: 'licenseUnavailable', secure_storage_unavailable: 'secureStorage', package_locked: 'needPurchase', plugin_price_invalid: 'priceInvalid', insufficient_balance: 'buyInsufficient', plugin_own: 'ownPlugin' };
    if (typeof error === 'string' && paid[error]) return appPluginText(locale, paid[error]);
    const inputError = appPluginInputError(locale, error);
    if (inputError) return inputError;
    // Purchase and marketplace codes (B20-03): the code stays in diagnostics, the user reads what happened.
    const market: Readonly<Record<string, AppPluginTextKey>> = { plugin_not_listed: 'error.notListed', plugin_not_found: 'error.notListed',
        plugin_free: 'error.free', plugin_purchase_idempotency_conflict: 'error.retryBuy', plugin_purchase_invalid: 'error.retryBuy', request_invalid: 'error.retryBuy',
        market_network: 'error.marketNetwork', market_failed: 'error.marketUnavailable' };
    if (typeof error === 'string' && market[error]) return appPluginText(locale, market[error]);
    if (typeof error === 'string' && /^market_http_\d{3}$/.test(error)) return appPluginText(locale, 'error.marketUnavailable');
    const key = `error.${typeof error === 'string' ? error : ''}` as AppPluginTextKey;
    if (key in zhCN) return appPluginText(locale, key);
    const failure = modelFailure(locale, error);
    if (typeof error !== 'string' || failure.kind !== 'unknown' || /^(?:decision|vision|model)_/.test(error)) return failure.text;
    return /^[a-z][a-z0-9]*(?:_[a-z0-9]+)+$/.test(error) ? appPluginText(locale, 'error.unknown') : appPluginText(locale, 'errorGeneric', { error });
}

export const APP_PLUGIN_TEXT_KEYS = Object.keys(zhCN) as AppPluginTextKey[];
export const APP_PLUGIN_TEXT_CATALOG = catalog;

/** Text lookups that never throw: an unknown key or language falls back (see nextmux-copy-fallback.ts). */
export function appPluginText(locale: Parameters<typeof uncheckedAppPluginText>[0], key: Parameters<typeof uncheckedAppPluginText>[1], ...rest: AfterLocaleAndKey<Parameters<typeof uncheckedAppPluginText>>): string {
    return totalCopy(locale, key, language => uncheckedAppPluginText(language, key, ...rest));
}
